using RailWerkz.Core.Audio;
using RailWerkz.Core.Settings;

namespace RailWerkz.UI;

/// The interface's sounds, generated by SoundForge at startup and played by the menus and widgets. Each has a few
/// takes to choose between in Options > Audio.
public static class Sfx
{
    /// One interface sound and the takes it can be swapped between; the choice is saved in the settings by name.
    public sealed class Slot(string label, string key, Func<Settings, string> get, Action<Settings, string> set, Action play, params (string Name, Func<Sound> Make)[] takes)
    {
        public string Label { get; } = label;

        public string Current => takes[Index].Name;

        private int Index => Math.Max(0, Array.FindIndex(takes, take => take.Name == get(Settings.Current)));

        public void Load() => AudioEngine.Add(key, takes[Index].Make());

        /// Steps to the next or previous take, loads it, and plays it.
        public void Cycle(int direction)
        {
            var index = (Index + direction + takes.Length) % takes.Length;
            set(Settings.Current, takes[index].Name);
            Load();
            play();
        }
    }

    public static readonly Slot[] Slots =
    [
        new("Hover sound", "ui.hover", s => s.HoverSound, (s, v) => s.HoverSound = v, Hover,
            ("GLASS", SoundForge.Hover), ("CLICK", SoundForge.Click), ("TAP", SoundForge.Tap), ("POP", SoundForge.Pop), ("RETRO", SoundForge.Blip)),
        new("Select sound", "ui.confirm", s => s.SelectSound, (s, v) => s.SelectSound = v, Select,
            ("BELLS", SoundForge.Confirm), ("CHIME", SoundForge.Chime), ("SOFT", SoundForge.Soft), ("KNOCK", SoundForge.Knock), ("RETRO", SoundForge.Select)),
        new("Back sound", "ui.dismiss", s => s.BackSound, (s, v) => s.BackSound = v, Back,
            ("BELLS", SoundForge.Dismiss), ("SOFT", SoundForge.SoftLow), ("KNOCK", SoundForge.KnockLow), ("RETRO", SoundForge.Back)),
        new("Typing sound", "ui.tick", s => s.TypingSound, (s, v) => s.TypingSound = v, Tick,
            ("NOISE", SoundForge.Tick), ("KEY", SoundForge.Key), ("MUFFLED", SoundForge.Muffled), ("PIP", SoundForge.Pip)),
    ];

    public static void Register()
    {
        foreach (var slot in Slots)
            slot.Load();
        AudioEngine.Add("ui.beep", SoundForge.Beep());
    }

    public static void Hover() => AudioEngine.Play("ui.hover", AudioCategory.Interface, 0.45f, 0.97f + Random.Shared.NextSingle() * 0.06f);
    public static void Select() => AudioEngine.Play("ui.confirm", AudioCategory.Interface, 0.55f);
    public static void Back() => AudioEngine.Play("ui.dismiss", AudioCategory.Interface, 0.55f);
    public static void Beep() => AudioEngine.Play("ui.beep", AudioCategory.Interface, 0.25f);
    public static void Tick() => AudioEngine.Play("ui.tick", AudioCategory.Interface, 0.35f, 0.9f + Random.Shared.NextSingle() * 0.2f);
}
